import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script path {script_path} does not exist")
    process = subprocess.Popen(['bash', script_path])
    start_time = time.time()
    cpu_usage = 0.0
    memory_usage = 0
    try:
        while process.poll() is None and time.time() - start_time < timeout:
            try:
                p = psutil.Process(process.pid)
                cpu_usage += p.cpu_percent(interval=0.1)
                memory_usage += p.memory_info().rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            time.sleep(0.1)
        if process.poll() is None:
            process.terminate()
            process.wait(timeout=1)
    except subprocess.TimeoutExpired:
        process.kill()
        process.wait()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

